import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Alert, AppState, Image, ImageBackground, KeyboardAvoidingView, Modal, Platform, Pressable, ScrollView, StatusBar, StyleSheet, Switch, Text, TextInput, View } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';
import { useFonts, Manrope_400Regular, Manrope_500Medium, Manrope_600SemiBold, Manrope_700Bold } from '@expo-google-fonts/manrope';

const STORAGE = 'ouren.local.v2';
const LOGO_URL = 'https://raw.githubusercontent.com/Audaa-Cyber/ouren/main/assets/ouren-logo.png';
const C = { paper:'#F2EEE7', white:'#F8F5EF', ink:'#20201D', muted:'#89867E', line:'#DED9D0', sand:'#D5CCBE', night:'#191A17', panel:'#282925', darkMuted:'#AAA69C' };
const MOUNTAIN = 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=1100&q=88';
const PLANT = 'https://images.unsplash.com/photo-1497250681960-ef046c08a56e?w=900&q=88';
const STONES = 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=900&q=88';
const FOREST = 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=1100&q=88';
const initialTasks = [
  { id:'a', title:'Deep work session', detail:'2h · Focus', category:'Focus', time:'9:00 AM', done:true },
  { id:'b', title:'Read 20 pages', detail:'30m · Growth', category:'Growth', time:'1:00 PM', done:false },
  { id:'c', title:'Workout', detail:'1h · Health', category:'Health', time:'4:00 PM', done:false },
  { id:'d', title:'Plan tomorrow', detail:'15m · Planning', category:'Planning', time:'', done:false },
];

function LogoMark({ size=25, color=C.ink }) {
  const [imageFailed, setImageFailed] = useState(false);
  return <View style={{width:size,height:size,alignItems:'center',justifyContent:'center'}}>
    {!imageFailed
      ? <Image source={{uri:LOGO_URL}} onError={()=>setImageFailed(true)} style={{width:size,height:size,tintColor:color}} resizeMode="contain" />
      : <View style={{width:size*.84,height:size*.84,borderWidth:size*.17,borderColor:color,borderRadius:size*.26,transform:[{rotate:'30deg'}],alignItems:'center',justifyContent:'center'}}>
          <Text style={{fontSize:size*.48,lineHeight:size*.52,color,fontFamily:'Manrope_700Bold',textAlign:'center'}}>✦</Text>
        </View>}
  </View>;
}
function Wordmark({ color=C.ink, size=18, mark=20 }) {
  return <View style={{flexDirection:'row',alignItems:'center',gap:7}}><LogoMark size={mark} color={color}/><Text style={{fontFamily:'Manrope_600SemiBold',fontSize:size,letterSpacing:2.2,color}}>ouren</Text></View>;
}
function ActionButton({ title, onPress, light=false, icon='arrow-forward', style }) {
  return <Pressable onPress={onPress} style={[s.actionButton,{backgroundColor:light?C.white:C.ink},style]}><Text style={{fontFamily:'Manrope_700Bold',fontSize:11,color:light?C.ink:'#FFFDF8'}}>{title}</Text><Ionicons name={icon} size={16} color={light?C.ink:'#FFFDF8'}/></Pressable>;
}
function Header({ dark=false, onProfile }) {
  return <View style={s.header}><Wordmark color={dark?C.white:C.ink} size={15} mark={20}/><Pressable onPress={onProfile} style={[s.headerAction,{borderColor:dark?'#4A4A43':C.line}]}><Ionicons name="ellipsis-horizontal" size={19} color={dark?C.white:C.ink}/></Pressable></View>;
}
function TaskItem({ task, onToggle, dark=false, showTime=false }) {
  const color = dark ? C.white : C.ink;
  return <Pressable onPress={onToggle} style={[s.taskItem,{borderBottomColor:dark?'#3A3B35':'#E8E3DA'}]}>
    <View style={[s.taskCheck,task.done&&{backgroundColor:color,borderColor:color}]}>{task.done&&<Ionicons name="checkmark" size={12} color={dark?C.ink:C.white}/>}</View>
    <View style={{flex:1}}>
      <Text style={[s.taskName,{color},task.done&&{textDecorationLine:'line-through',opacity:.58}]}>{task.title}</Text>
      <Text style={[s.taskMeta,{color:dark?C.darkMuted:C.muted}]}>{task.priority==='High'?'HIGH PRIORITY · ':''}{task.detail}</Text>
    </View>
    {showTime&&!!task.time&&<Text style={[s.taskTime,{color:dark?C.darkMuted:C.muted}]}>{task.time}</Text>}
  </Pressable>;
}
function Dots({ active, dark=false }) {
  return <View style={s.dots}>{[0,1,2].map(i=><View key={i} style={{width:i===active?10:5,height:3,borderRadius:4,backgroundColor:i===active?(dark?C.white:C.ink):(dark?'#65645C':'#C9C3B8'),marginHorizontal:5}}/>)}</View>;
}

Notifications.setNotificationHandler({
  handleNotification: async () => ({ shouldShowAlert:true, shouldPlaySound:false, shouldSetBadge:false }),
});

export default function App() {
  const [fontsLoaded] = useFonts({Manrope_400Regular,Manrope_500Medium,Manrope_600SemiBold,Manrope_700Bold});
  const [ready,setReady] = useState(false);
  const [profile,setProfile] = useState(null);
  const [onboarding,setOnboarding] = useState(0);
  const [tab,setTab] = useState('Home');
  const [tasks,setTasks] = useState(initialTasks);
  const [dark,setDark] = useState(false);
  const [notifications,setNotifications] = useState(true);
  const [focusLength,setFocusLength] = useState(25);
  const [timerEndsAt,setTimerEndsAt] = useState(null);
  const [activeSession,setActiveSession] = useState(null);
  const [sessionHistory,setSessionHistory] = useState([]);
  const [focusTaskId,setFocusTaskId] = useState(null);
  const [taskPickerVisible,setTaskPickerVisible] = useState(false);
  const [seconds,setSeconds] = useState(1500);
  const [running,setRunning] = useState(false);
  const [mode,setMode] = useState('Focus');
  const [monthOffset,setMonthOffset] = useState(0);
  const [selectedDay,setSelectedDay] = useState(new Date().getDate());
  const [taskModal,setTaskModal] = useState(false);
  const [taskFilter,setTaskFilter] = useState('Today');
  const [editModal,setEditModal] = useState(false);
  const [taskName,setTaskName] = useState('');
  const [category,setCategory] = useState('Focus');
  const [taskPriority,setTaskPriority] = useState('Normal');
  const [taskEstimate,setTaskEstimate] = useState(30);
  const [name,setName] = useState('');
  const [email,setEmail] = useState('');
  const timer = useRef(null);
  const completedTimerRef = useRef(false);

  useEffect(()=>{(async()=>{try{const raw=await AsyncStorage.getItem(STORAGE);if(raw){const d=JSON.parse(raw);setProfile(d.profile||null);setTasks(Array.isArray(d.tasks)?d.tasks:initialTasks);setDark(!!d.dark);setNotifications(d.notifications!==false);setFocusLength(d.focusLength||25);setSeconds(d.timerRunning&&d.timerEndsAt?Math.max(0,Math.ceil((d.timerEndsAt-Date.now())/1000)):(d.seconds??(d.focusLength||25)*60));setRunning(!!(d.timerRunning&&d.timerEndsAt>Date.now()));setTimerEndsAt(d.timerRunning&&d.timerEndsAt>Date.now()?d.timerEndsAt:null);const restoredHistory=Array.isArray(d.sessionHistory)?d.sessionHistory:[];const restoredActive=d.activeSession||null;const expiredRunningSession=!!(d.timerRunning&&d.timerEndsAt&&d.timerEndsAt<=Date.now()&&restoredActive);setActiveSession(expiredRunningSession?null:restoredActive);setSessionHistory(expiredRunningSession?[{...restoredActive,completedAt:d.timerEndsAt,durationSeconds:restoredActive.plannedSeconds},...restoredHistory].slice(0,500):restoredHistory);setFocusTaskId(d.focusTaskId||null);setOnboarding(d.profile?4:0);}}catch(e){console.warn('Restore failed',e);}finally{setReady(true);}})();},[]);
  useEffect(()=>{
    // Remove legacy sleep reminders from earlier app builds; Ouren intentionally has no sleep-protection feature.
    Notifications.getAllScheduledNotificationsAsync()
      .then(items=>Promise.all(items.filter(item=>item.content?.data?.ourenSleepReminder).map(item=>Notifications.cancelScheduledNotificationAsync(item.identifier))))
      .catch(error=>console.warn('Legacy reminder cleanup skipped',error));
  },[]);
  useEffect(()=>{if(ready&&profile)AsyncStorage.setItem(STORAGE,JSON.stringify({profile,tasks,dark,notifications,focusLength,seconds,timerRunning:running,timerEndsAt,activeSession,sessionHistory,focusTaskId})).catch(e=>console.warn('Save failed',e));},[ready,profile,tasks,dark,notifications,focusLength,seconds,running,timerEndsAt,activeSession,sessionHistory,focusTaskId]);
  useEffect(()=>{
    if(!running||!timerEndsAt)return undefined;
    const updateRemaining=()=>{
      const remaining=Math.max(0,Math.ceil((timerEndsAt-Date.now())/1000));
      setSeconds(remaining);
      if(remaining===0&&!completedTimerRef.current){
        completedTimerRef.current=true;
        setRunning(false);
        setTimerEndsAt(null);
        if(activeSession){
          if(activeSession.mode==='Focus'){
            const completed={...activeSession,completedAt:Date.now(),durationSeconds:activeSession.plannedSeconds};
            setSessionHistory(previous=>[completed,...previous].slice(0,500));
          }
          setActiveSession(null);
        }
        Alert.alert('Session complete','Take a breath. You made space for what matters.');
      }
    };
    updateRemaining();
    timer.current=setInterval(updateRemaining,250);
    const subscription=AppState.addEventListener('change',state=>{if(state==='active')updateRemaining();});
    return()=>{if(timer.current)clearInterval(timer.current);subscription.remove();};
  },[running,timerEndsAt,activeSession]);
  const today = new Date();
  const shownMonth = new Date(today.getFullYear(),today.getMonth()+monthOffset,1);
  const monthDays = useMemo(()=>{const first=new Date(shownMonth.getFullYear(),shownMonth.getMonth(),1).getDay();const count=new Date(shownMonth.getFullYear(),shownMonth.getMonth()+1,0).getDate();return [...Array(first).fill(null),...Array.from({length:count},(_,i)=>i+1)];},[monthOffset,ready]);
  const done = tasks.filter(t=>t.done).length;
  const palette = dark?{bg:C.night,card:C.panel,text:C.white,muted:C.darkMuted,line:'#3D3E37'}:{bg:C.paper,card:C.white,text:C.ink,muted:C.muted,line:C.line};
  const greet = today.getHours()<12?'Good morning':today.getHours()<18?'Good afternoon':'Good evening';
  const clock = String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');

  const saveProfile=()=>{if(!name.trim()){Alert.alert('Your name','Enter your name to continue.');return;}setProfile({name:name.trim(),email:email.trim()});setOnboarding(4);setTab('Home');};
  const addTask=()=>{if(!taskName.trim())return;setTasks(prev=>[{id:String(Date.now()),title:taskName.trim(),detail:taskEstimate+'m · '+category,category,priority:taskPriority,estimateMinutes:taskEstimate,time:'',done:false},...prev]);setTaskName('');setTaskPriority('Normal');setTaskEstimate(30);setTaskModal(false);setTab('Tasks');};
  const toggleTask=id=>setTasks(prev=>prev.map(t=>t.id===id?{...t,done:!t.done}:t));
  const openProfile=()=>{setName(profile?.name||'');setEmail(profile?.email||'');setEditModal(true);};
  const saveEditedProfile=()=>{if(!name.trim())return;setProfile({name:name.trim(),email:email.trim()});setEditModal(false);};
  const resetTimer=()=>{setRunning(false);setTimerEndsAt(null);setSeconds(focusLength*60);completedTimerRef.current=false;};
  const toggleTimer=()=>{
    if(running){
      setRunning(false);
      setTimerEndsAt(null);
      return;
    }
    const remaining=seconds>0?seconds:focusLength*60;
    completedTimerRef.current=false;
    if(mode==='Focus'&&!activeSession){const selectedTask=tasks.find(task=>task.id===focusTaskId);setActiveSession({id:String(Date.now()),startedAt:Date.now(),mode,plannedSeconds:remaining,taskId:selectedTask?.id||null,taskTitle:selectedTask?.title||null});}
    setSeconds(remaining);
    setTimerEndsAt(Date.now()+remaining*1000);
    setRunning(true);
  };
  const discardSession=()=>{setRunning(false);setTimerEndsAt(null);setActiveSession(null);setSeconds(focusLength*60);completedTimerRef.current=false;};
  const renderProgress=()=>{
    const dayStart=new Date();dayStart.setHours(0,0,0,0);const dayEnd=dayStart.getTime()+86400000;
    const todaySessions=sessionHistory.filter(item=>(item.completedAt||0)>=dayStart.getTime()&&(item.completedAt||0)<dayEnd);const todayFocus=todaySessions.reduce((sum,item)=>sum+(item.durationSeconds||0),0);
    const week=Array.from({length:7},(_,index)=>{const date=new Date(dayStart.getTime()-(6-index)*86400000);const end=date.getTime()+86400000;const sessions=sessionHistory.filter(item=>(item.completedAt||0)>=date.getTime()&&(item.completedAt||0)<end);return {date,seconds:sessions.reduce((sum,item)=>sum+(item.durationSeconds||0),0),count:sessions.length};});const maxWeekSeconds=Math.max(1,...week.map(day=>day.seconds));const totalSeconds=sessionHistory.reduce((sum,item)=>sum+(item.durationSeconds||0),0);const formatDuration=seconds=>{const mins=Math.round(seconds/60);return mins<60?mins+'m':Math.floor(mins/60)+'h '+mins%60+'m';};const taskCounts={};sessionHistory.forEach(item=>{if(item.taskTitle)taskCounts[item.taskTitle]=(taskCounts[item.taskTitle]||0)+(item.durationSeconds||0);});const mostFocused=Object.entries(taskCounts).sort((a,b)=>b[1]-a[1])[0];
    return <View style={[s.lightScreen,{backgroundColor:C.paper}]}><View style={s.historyTop}><Pressable onPress={()=>setTab('Home')} style={s.historyBack}><Ionicons name="arrow-back" size={18} color={C.ink}/></Pressable><Text style={s.historyEyebrow}>PROGRESS INTELLIGENCE</Text><View style={{width:36}}/></View><View style={s.historyIntro}><Text style={s.pageTitle}>Your progress</Text><Text style={s.pageSubtitle}>Notice the effort. Build on it gently.</Text></View><View style={s.progressHero}><Text style={s.progressHeroLabel}>TODAY'S FOCUS</Text><Text style={s.progressHeroValue}>{formatDuration(todayFocus)}</Text><Text style={s.progressHeroNote}>{todaySessions.length} completed focus {todaySessions.length===1?'session':'sessions'}</Text><View style={s.progressHeroDivider}/><View style={s.progressHeroBottom}><View><Text style={s.progressHeroSmall}>{sessionHistory.length}</Text><Text style={s.progressHeroTiny}>ALL SESSIONS</Text></View><View><Text style={s.progressHeroSmall}>{formatDuration(totalSeconds)}</Text><Text style={s.progressHeroTiny}>TOTAL FOCUS</Text></View><View><Text style={s.progressHeroSmall}>{tasks.length?Math.round(done/tasks.length*100):0}%</Text><Text style={s.progressHeroTiny}>TASKS DONE</Text></View></View></View><View style={s.progressChartCard}><View style={s.progressCardHeading}><Text style={s.historySectionTitle}>Last 7 days</Text><Text style={s.progressCardCaption}>FOCUS TIME</Text></View><View style={s.progressBars}>{week.map((day,index)=><View key={day.date.toISOString()} style={s.progressBarColumn}><Text style={s.progressBarValue}>{day.seconds?formatDuration(day.seconds):''}</Text><View style={s.progressBarTrack}><View style={[s.progressBarFill,{height:Math.max(day.seconds?5:2,day.seconds/maxWeekSeconds*100)+'%'}]}/></View><Text style={[s.progressBarDay,index===6&&{color:C.ink,fontFamily:'Manrope_700Bold'}]}>{day.date.toLocaleDateString('en-US',{weekday:'short'}).slice(0,1)}</Text></View>)}</View></View><View style={s.progressInsight}><View style={s.progressInsightIcon}><Ionicons name="leaf-outline" size={18} color={C.ink}/></View><View style={{flex:1}}><Text style={s.progressInsightLabel}>A SMALL INSIGHT</Text><Text style={s.progressInsightTitle}>{mostFocused?mostFocused[0]:'Your first session is waiting'}</Text><Text style={s.progressInsightText}>{mostFocused?'Your most focused task, with '+formatDuration(mostFocused[1])+' invested.':'Finish a focus session to start seeing patterns in your work.'}</Text></View></View></View>;
  };

  const renderHistory=()=>{
    const completedSeconds=sessionHistory.reduce((sum,item)=>sum+(item.durationSeconds||0),0);
    const todayKey=new Date().toDateString();
    const todaySessions=sessionHistory.filter(item=>new Date(item.completedAt||item.startedAt).toDateString()===todayKey);
    const formatDuration=seconds=>{const mins=Math.round(seconds/60);return mins<60?mins+' min':Math.floor(mins/60)+'h '+mins%60+'m';};
    return <View style={[s.lightScreen,{backgroundColor:C.paper}]}>
      <View style={s.historyTop}><Pressable onPress={()=>setTab('Focus')} style={s.historyBack}><Ionicons name="arrow-back" size={18} color={C.ink}/></Pressable><Text style={s.historyEyebrow}>YOUR PRACTICE</Text><View style={{width:36}}/></View>
      <View style={s.historyIntro}><Text style={s.pageTitle}>Focus history</Text><Text style={s.pageSubtitle}>Every session is a small promise kept.</Text></View>
      <View style={s.historyStats}><View style={s.historyStat}><Text style={s.historyStatValue}>{formatDuration(todaySessions.reduce((sum,item)=>sum+(item.durationSeconds||0),0))}</Text><Text style={s.historyStatLabel}>TODAY</Text></View><View style={s.historyStatDivider}/><View style={s.historyStat}><Text style={s.historyStatValue}>{sessionHistory.length}</Text><Text style={s.historyStatLabel}>SESSIONS</Text></View><View style={s.historyStatDivider}/><View style={s.historyStat}><Text style={s.historyStatValue}>{formatDuration(completedSeconds)}</Text><Text style={s.historyStatLabel}>TOTAL FOCUS</Text></View></View>
      <View style={s.historySectionHeader}><Text style={s.historySectionTitle}>Recent sessions</Text><Text style={s.historySectionMeta}>{sessionHistory.length?'LATEST FIRST':'YOUR JOURNEY STARTS HERE'}</Text></View>
      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{paddingBottom:24}}>{sessionHistory.length===0?<View style={s.historyEmpty}><View style={s.historyEmptyIcon}><Ionicons name="hourglass-outline" size={23} color={C.muted}/></View><Text style={s.historyEmptyTitle}>Your progress starts with one session.</Text><Text style={s.historyEmptyText}>Complete a focus session and it will appear here. Paused or abandoned sessions aren't counted.</Text><ActionButton title="Start focusing" onPress={()=>setTab('Focus')} style={{marginTop:20}}/></View>:sessionHistory.map(item=><View key={item.id} style={s.historyRow}><View style={s.historyRowIcon}><Ionicons name={item.mode==='Break'?'cafe-outline':'flame-outline'} size={18} color={C.ink}/></View><View style={{flex:1}}><Text style={s.historyRowTitle}>{item.taskTitle||((item.mode||'Focus')+' session')}</Text><Text style={s.historyRowMeta}>{item.taskTitle?((item.mode||'Focus')+' · '):''}{new Date(item.completedAt||item.startedAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · {new Date(item.completedAt||item.startedAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</Text></View><Text style={s.historyRowDuration}>{formatDuration(item.durationSeconds||0)}</Text></View>)}</ScrollView>
      {sessionHistory.length>0&&<Pressable onPress={()=>Alert.alert('Clear focus history?','This permanently removes your completed sessions from this device.',[{text:'Cancel',style:'cancel'},{text:'Clear history',style:'destructive',onPress:()=>setSessionHistory([])}])} style={s.historyClear}><Text style={s.historyClearText}>Clear history</Text></Pressable>}
    </View>;
  };
  if(!fontsLoaded||!ready)return <View style={s.loading}><LogoMark size={48}/><Text style={s.loadingWord}>ouren</Text></View>;

  // First-launch onboarding is only shown until the local profile is created.
  if(!profile) {
    const slides=[
      {title:'A calmer mind\nbuilds a bigger\nfuture.',body:'Ouren helps you focus, plan and make real progress — one day at a time.',image:MOUNTAIN,cover:true},
      {title:'Focus on\nwhat matters.',body:'Block distractions, set your intentions, and give your best energy to what counts.',image:PLANT},
      {title:'Small steps.\nBig results.',body:'Turn your goals into simple actions and watch your progress grow.',image:STONES},
    ];
    if(onboarding===0)return <View style={{flex:1,backgroundColor:C.paper}}><StatusBar barStyle="dark-content"/><ImageBackground source={{uri:MOUNTAIN}} resizeMode="cover" style={s.splashImage}><LinearGradient colors={['rgba(242,238,231,.08)','rgba(242,238,231,.14)','rgba(25,26,23,.82)']} style={s.splashShade}><View style={s.splashBrand}><LogoMark size={58}/><Text style={s.splashWord}>ouren</Text></View><View style={s.splashBottom}><Text style={s.splashTag}>Focus today.{"\n"}Build tomorrow.</Text><ActionButton title="Get started" onPress={()=>setOnboarding(1)} style={{marginTop:26}}/></View></LinearGradient></ImageBackground></View>;
    if(onboarding>=1&&onboarding<=3){const slide=slides[onboarding-1];return <View style={s.onboardScreen}><StatusBar barStyle="dark-content"/><View style={s.onboardTop}><Text style={s.tinyTime}>9:41</Text><View style={s.statusGlyphs}><Ionicons name="cellular" size={12} color={C.ink}/><Ionicons name="wifi" size={12} color={C.ink}/><Ionicons name="battery-full" size={15} color={C.ink}/></View></View><ScrollView contentContainerStyle={s.onboardBody} showsVerticalScrollIndicator={false}>{!slide.cover&&<ImageBackground source={{uri:slide.image}} style={s.onboardPhoto} imageStyle={{borderRadius:18}}/>}<View style={s.onboardCopy}><Text style={s.onboardTitle}>{slide.title}</Text><Text style={s.onboardDescription}>{slide.body}</Text></View><Dots active={onboarding-1}/><ActionButton title="Get started" onPress={()=>setOnboarding(onboarding===3?4:onboarding+1)} style={{marginTop:20}}/></ScrollView><View style={s.homeIndicatorLight}/></View>}
    if(onboarding===4)return <KeyboardAvoidingView style={s.setupScreen} behavior={Platform.OS==='ios'?'padding':undefined}><StatusBar barStyle="light-content"/><Pressable onPress={()=>setOnboarding(3)} style={s.backButton}><Ionicons name="arrow-back" size={19} color={C.white}/></Pressable><View style={s.setupCenter}><View style={s.setupLogo}><LogoMark size={34} color={C.white}/></View><Text style={s.setupWord}>ouren</Text><Text style={s.setupSub}>Better days, by design.</Text><View style={s.setupForm}><Text style={s.setupPrompt}>Make this space yours.</Text><Text style={s.setupHint}>Your profile is saved on this device.</Text><TextInput value={name} onChangeText={setName} placeholder="Your name" placeholderTextColor="#A9A69E" style={s.inputDark}/><TextInput value={email} onChangeText={setEmail} placeholder="Email (optional)" placeholderTextColor="#A9A69E" autoCapitalize="none" keyboardType="email-address" style={s.inputDark}/><ActionButton title="Continue" onPress={saveProfile} style={{marginTop:12}}/></View></View><Text style={s.setupPrivacy}>PRIVATE BY DESIGN · STORED LOCALLY</Text></KeyboardAvoidingView>;
  }

  const renderHome=()=> <View style={{flex:1,backgroundColor:C.night}}><ImageBackground source={{uri:MOUNTAIN}} resizeMode="cover" style={s.homePhoto} imageStyle={{opacity:.48}}><LinearGradient colors={['rgba(17,18,16,.28)','rgba(17,18,16,.38)','rgba(17,18,16,.97)']} style={s.homeShade}><View style={s.homeTop}><LogoMark size={24} color={C.white}/><Pressable onPress={()=>setTab('Settings')} style={s.profileMini}><Text style={s.profileInitial}>{profile.name.slice(0,1).toUpperCase()}</Text></Pressable></View><View style={s.homeGreeting}><Text style={s.greetingTitle}>{greet},{'\n'}{profile.name}.</Text><Text style={s.greetingSub}>Your focus creates{"\n"}your future.</Text></View><View style={s.todayCard}><View style={s.todayHeader}><Text style={s.todayHeading}>Today</Text><Text style={s.todayDate}>{today.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</Text></View>{tasks.slice(0,4).map(t=><TaskItem key={t.id} task={t} onToggle={()=>toggleTask(t.id)} dark/> )}</View><Pressable onPress={()=>setTab('Progress')} style={s.homeProgress}><Text style={s.homeProgressLabel}>YOUR DAILY RHYTHM · VIEW PROGRESS ↗</Text><Text style={s.homeProgressValue}>{done} of {tasks.length} complete</Text><View style={s.progressTrack}><View style={[s.progressFill,{width:(tasks.length?done/tasks.length*100:0)+'%'}]}/></View></View></LinearGradient></ImageBackground></View>;

  const renderFocus=()=> <View style={{flex:1,backgroundColor:C.night}}><ImageBackground source={{uri:FOREST}} resizeMode="cover" style={s.focusPhoto} imageStyle={{opacity:.55}}><LinearGradient colors={['rgba(15,16,14,.45)','rgba(15,16,14,.5)','rgba(15,16,14,.7)']} style={s.focusShade}><View style={s.focusHeader}><Pressable onPress={()=>setTab('Home')} style={s.glassButton}><Ionicons name="close" size={19} color={C.white}/></Pressable><View style={{flexDirection:'row',gap:8}}><Pressable onPress={()=>setTab('History')} style={s.glassButton}><Ionicons name="time-outline" size={18} color={C.white}/></Pressable><Pressable onPress={()=>setTab('Settings')} style={s.glassButton}><Ionicons name="settings-outline" size={18} color={C.white}/></Pressable></View></View><View style={s.timerArea}><View style={s.timerRing}><View style={s.timerArc}/><Text style={s.timerMode}>{mode}</Text><Text style={s.timerDigits}>{clock}</Text><Text style={s.timerCaption}>{running?'Stay in the moment':'Work'}</Text></View><Pressable onPress={toggleTimer} style={s.timerPlay}><Ionicons name={running?'pause':'play'} size={24} color={C.ink}/></Pressable></View><View style={s.focusModes}>{[{name:'Break',icon:'timer-outline'},{name:'Focus',icon:'flame-outline'},{name:'Music',icon:'musical-notes-outline'}].map(m=><Pressable key={m.name} onPress={()=>{setMode(m.name);if(m.name!=='Music'){setRunning(false);setTimerEndsAt(null);setActiveSession(null);const n=m.name==='Break'?5:25;setFocusLength(n);setSeconds(n*60);completedTimerRef.current=false;}}} style={s.focusModeButton}><Ionicons name={m.icon} size={18} color={C.white}/><Text style={s.focusModeText}>{m.name}</Text></Pressable>)}</View><Pressable onPress={()=>setTaskPickerVisible(true)} style={s.focusTaskPicker}><Ionicons name="checkbox-outline" size={15} color={C.white}/><Text numberOfLines={1} style={s.focusTaskPickerText}>{tasks.find(task=>task.id===focusTaskId)?.title||'Link this session to a task'}</Text><Ionicons name="chevron-down" size={14} color={C.darkMuted}/></Pressable></LinearGradient></ImageBackground></View>;

  const renderTasks=()=> {const visibleTasks=taskFilter==='Completed'?tasks.filter(task=>task.done):taskFilter==='Upcoming'?tasks.filter(task=>!task.done&&!!task.time):tasks.filter(task=>!task.done);return <View style={[s.lightScreen,{backgroundColor:C.paper}]}><Header onProfile={()=>setTab('Settings')}/><View style={s.pageHeadingRow}><View><Text style={s.pageTitle}>Tasks</Text><Text style={s.pageSubtitle}>A little progress, every day.</Text></View><Pressable onPress={()=>setTaskModal(true)} style={s.addCircle}><Ionicons name="add" size={24} color={C.white}/></Pressable></View><View style={s.taskFilters}>{['Today','Upcoming','Completed'].map(v=><Pressable key={v} onPress={()=>setTaskFilter(v)} style={[s.filterItem,taskFilter===v&&s.filterActive]}><Text style={[s.filterText,taskFilter===v&&s.filterTextActive]}>{v}</Text></Pressable>)}</View><ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{paddingBottom:22}}><View style={s.lightTaskList}>{visibleTasks.length?visibleTasks.map(t=><TaskItem key={t.id} task={t} onToggle={()=>toggleTask(t.id)}/>):<Text style={s.taskEmpty}>{taskFilter==='Completed'?'Completed tasks will appear here.':taskFilter==='Upcoming'?'No scheduled tasks yet. Add a task with a time to see it here.':'You are all caught up. Add a task when you are ready.'}</Text>}</View></ScrollView><View style={s.floatingAdd}><Pressable onPress={()=>setTaskModal(true)} style={s.floatingAddButton}><Ionicons name="add" size={25} color={C.white}/></Pressable></View></View>;};

  const renderCalendar=()=> <View style={[s.lightScreen,{backgroundColor:C.paper}]}><Header onProfile={()=>setTab('Settings')}/><View style={s.calendarMonthRow}><Text style={s.pageTitleSmall}>{shownMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</Text><View style={{flexDirection:'row',gap:20}}><Pressable onPress={()=>{setMonthOffset(x=>x-1);setSelectedDay(1);}}><Ionicons name="chevron-back" size={18} color={C.ink}/></Pressable><Pressable onPress={()=>{setMonthOffset(x=>x+1);setSelectedDay(1);}}><Ionicons name="chevron-forward" size={18} color={C.ink}/></Pressable></View></View><View style={s.calendarGrid}>{['S','M','T','W','T','F','S'].map((d,i)=><Text key={d+i} style={s.weekday}>{d}</Text>)}{monthDays.map((d,i)=><Pressable key={i} onPress={()=>d&&setSelectedDay(d)} style={[s.dayCell,d===selectedDay&&s.daySelected]}><Text style={[s.dayNumber,d===selectedDay&&s.dayNumberSelected]}>{d||''}</Text></Pressable>)}</View><View style={s.scheduleHeading}><Text style={s.scheduleTitle}>{monthOffset===0&&selectedDay===today.getDate()?'Today':today.toLocaleDateString('en-US',{month:'short'})+' '+selectedDay}</Text><Text style={s.scheduleDate}>{tasks.filter(t=>!t.done).length} tasks</Text></View><ScrollView showsVerticalScrollIndicator={false}><View style={s.scheduleList}>{tasks.map(t=><TaskItem key={t.id} task={t} onToggle={()=>toggleTask(t.id)} showTime/>)}</View></ScrollView></View>;

  const renderSettings=()=> <View style={s.settingsScreen}><View style={s.settingsTop}><Pressable onPress={()=>setTab('Home')}><Ionicons name="arrow-back" size={18} color={C.darkMuted}/></Pressable><View style={{flex:1}}/></View><View style={s.settingsBrand}><View style={s.settingsLogoBox}><LogoMark size={29} color={C.white}/></View><Text style={s.settingsWord}>ouren</Text><Text style={s.settingsTagline}>Better days, by design.</Text></View><Pressable onPress={()=>{setName(profile.name);setEmail(profile.email||'');setEditModal(true);}} style={s.accountCard}><View style={s.accountAvatar}><Text style={s.accountInitial}>{profile.name.slice(0,1).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.accountName}>{profile.name}</Text><Text style={s.accountEmail}>{profile.email||'Personal space'}</Text></View><Ionicons name="chevron-forward" size={17} color={C.darkMuted}/></Pressable><View style={s.settingsList}>{[{icon:'person-outline',label:'Account',sub:'Profile details',action:openProfile},{icon:'notifications-outline',label:'Notifications',sub:'Gentle reminders',action:()=>setNotifications(v=>!v),toggle:true},{icon:'contrast-outline',label:'Appearance',sub:dark?'Dark mode':'Light mode',action:()=>setDark(v=>!v),toggle:true,value:dark},{icon:'timer-outline',label:'Focus settings',sub:focusLength+' minute sessions',action:()=>{const n=focusLength===25?45:focusLength===45?50:25;setFocusLength(n);setSeconds(n*60);setTimerEndsAt(null);setRunning(false);setActiveSession(null);},},{icon:'shield-checkmark-outline',label:'Privacy & security',sub:'Your data stays on this device',action:()=>Alert.alert('Private by design','Ouren stores your profile, tasks and preferences on this device. There is no cloud account connected.')},{icon:'help-circle-outline',label:'Help & support',sub:'About Ouren',action:()=>Alert.alert('Ouren','Focus today. Build tomorrow.')}].map((item,i)=><Pressable key={item.label} onPress={item.action} style={[s.settingRow,i>0&&{borderTopWidth:1,borderTopColor:'#393A34'}]}><Ionicons name={item.icon} size={17} color={C.darkMuted}/><View style={{flex:1}}><Text style={s.settingLabel}>{item.label}</Text><Text style={s.settingSub}>{item.sub}</Text></View>{item.toggle?<Switch value={item.label==='Notifications'?notifications:dark} onValueChange={item.label==='Notifications'?setNotifications:setDark} trackColor={{false:'#494A43',true:'#A8A397'}} thumbColor={C.white}/>:<Ionicons name="chevron-forward" size={16} color={C.darkMuted}/>}</Pressable>)}</View><Pressable onPress={()=>Alert.alert('Log out of this device?','This removes your local profile and app data.',[{text:'Cancel',style:'cancel'},{text:'Log out',style:'destructive',onPress:async()=>{await AsyncStorage.removeItem(STORAGE);setProfile(null);setTasks(initialTasks);setSessionHistory([]);setActiveSession(null);setRunning(false);setTimerEndsAt(null);setOnboarding(0);setTab('Home');setDark(false);setNotifications(true);setName('');setEmail('');}}])} style={s.logoutButton}><Text style={s.logoutText}>Log out</Text></Pressable></View>;

  return <View style={{flex:1,backgroundColor:palette.bg}}><StatusBar barStyle={tab==='Home'||tab==='Focus'||tab==='Settings'?'light-content':'dark-content'} />
    <View style={{flex:1}}>{tab==='Home'&&renderHome()}{tab==='Focus'&&renderFocus()}{tab==='Tasks'&&renderTasks()}{tab==='Calendar'&&renderCalendar()}{tab==='Settings'&&renderSettings()}{tab==='History'&&renderHistory()}{tab==='Progress'&&renderProgress()}</View>
    {tab!=='Settings'&&tab!=='Focus'&&tab!=='History'&&tab!=='Progress'&&<View style={[s.tabBar,{backgroundColor:tab==='Home'||tab==='Focus'?C.night:C.paper,borderTopColor:tab==='Home'||tab==='Focus'?'#33342F':'#E1DCD3'}]}>{[{key:'Home',icon:'home-outline'},{key:'Tasks',icon:'checkbox-outline'},{key:'Focus',icon:'radio-button-on-outline'},{key:'Calendar',icon:'calendar-outline'}].map(n=><Pressable key={n.key} onPress={()=>setTab(n.key)} style={s.tabItem}><Ionicons name={n.icon} size={17} color={tab===n.key?(tab==='Home'||tab==='Focus'?C.white:C.ink):(tab==='Home'||tab==='Focus'?'#89877F':'#969187')}/><Text style={[s.tabLabel,{color:tab===n.key?(tab==='Home'||tab==='Focus'?C.white:C.ink):(tab==='Home'||tab==='Focus'?'#89877F':'#969187')}]}>{n.key}</Text></Pressable>)}</View>}
    <Modal visible={taskModal} transparent animationType="slide" onRequestClose={()=>setTaskModal(false)}><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={s.modalShade}><Pressable style={StyleSheet.absoluteFill} onPress={()=>setTaskModal(false)}/><View style={s.modalCard}><View style={s.modalHandle}/><View style={s.modalTitleRow}><Text style={s.modalTitle}>Add a task</Text><Pressable onPress={()=>setTaskModal(false)}><Ionicons name="close" size={22} color={C.muted}/></Pressable></View><TextInput value={taskName} onChangeText={setTaskName} placeholder="What would you like to do?" placeholderTextColor="#9A958B" style={s.inputLight}/><Text style={s.categoryCaption}>CATEGORY</Text><View style={s.categoryPills}>{['Focus','Growth','Health','Planning'].map(v=><Pressable key={v} onPress={()=>setCategory(v)} style={[s.categoryPill,category===v&&{backgroundColor:C.sand}]}><Text style={s.categoryText}>{v}</Text></Pressable>)}</View><Text style={s.categoryCaption}>PRIORITY</Text><View style={s.categoryPills}>{['Low','Normal','High'].map(v=><Pressable key={v} onPress={()=>setTaskPriority(v)} style={[s.categoryPill,taskPriority===v&&{backgroundColor:C.sand}]}><Text style={s.categoryText}>{v}</Text></Pressable>)}</View><Text style={s.categoryCaption}>TIME ESTIMATE</Text><View style={s.categoryPills}>{[15,25,30,45,60,90].map(v=><Pressable key={v} onPress={()=>setTaskEstimate(v)} style={[s.categoryPill,taskEstimate===v&&{backgroundColor:C.sand}]}><Text style={s.categoryText}>{v>=60?(v/60)+'h':v+' min'}</Text></Pressable>)}</View><ActionButton title="Save task" icon="checkmark" onPress={addTask} style={{marginTop:22}}/></View></KeyboardAvoidingView></Modal>
    <Modal visible={taskPickerVisible} transparent animationType="slide" onRequestClose={()=>setTaskPickerVisible(false)}><View style={s.modalShade}><Pressable style={StyleSheet.absoluteFill} onPress={()=>setTaskPickerVisible(false)}/><View style={s.modalCard}><View style={s.modalHandle}/><View style={s.modalTitleRow}><Text style={s.modalTitle}>Focus on a task</Text><Pressable onPress={()=>setTaskPickerVisible(false)}><Ionicons name="close" size={22} color={C.muted}/></Pressable></View><Text style={s.taskPickerHint}>Choose what this session is for. It will be saved with your focus history.</Text><ScrollView style={{maxHeight:310}}><Pressable onPress={()=>{setFocusTaskId(null);setTaskPickerVisible(false);}} style={s.taskPickerRow}><View style={s.taskPickerRadio}>{!focusTaskId&&<View style={s.taskPickerRadioInner}/>}</View><Text style={s.taskPickerText}>Focus without a task</Text></Pressable>{tasks.filter(task=>!task.done).map(task=><Pressable key={task.id} onPress={()=>{setFocusTaskId(task.id);setTaskPickerVisible(false);}} style={s.taskPickerRow}><View style={s.taskPickerRadio}>{focusTaskId===task.id&&<View style={s.taskPickerRadioInner}/>}</View><View style={{flex:1}}><Text style={s.taskPickerText}>{task.title}</Text><Text style={s.taskPickerMeta}>{task.category||'Task'}{task.detail?' · '+task.detail:''}</Text></View></Pressable>)}</ScrollView>{tasks.every(task=>task.done)&&<Text style={s.taskPickerHint}>All your tasks are complete. Add a task from the Tasks tab to link it here.</Text>}</View></View></Modal>
    <Modal visible={editModal} transparent animationType="fade" onRequestClose={()=>setEditModal(false)}><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={s.modalShade}><Pressable style={StyleSheet.absoluteFill} onPress={()=>setEditModal(false)}/><View style={s.modalCard}><View style={s.modalTitleRow}><Text style={s.modalTitle}>Your account</Text><Pressable onPress={()=>setEditModal(false)}><Ionicons name="close" size={22} color={C.muted}/></Pressable></View><TextInput value={name} onChangeText={setName} placeholder="Your name" placeholderTextColor="#9A958B" style={s.inputLight}/><TextInput value={email} onChangeText={setEmail} placeholder="Email (optional)" placeholderTextColor="#9A958B" autoCapitalize="none" keyboardType="email-address" style={[s.inputLight,{marginTop:10}]}/><ActionButton title="Save changes" onPress={saveEditedProfile} style={{marginTop:18}}/></View></KeyboardAvoidingView></Modal>
  </View>;
}

